SELECT
p.*,
c.customer_name
FROM mis_sales_payment_plan p
LEFT JOIN mis_customer c ON p.customer_id = c.id
WHERE p.del_flag = '0'

    AND p.plan_no LIKE CONCAT('%', #{vo.planNo}, '%')


    AND o.sales_order_no LIKE CONCAT('%', #{vo.salesOrderNo}, '%')


      AND p.customer_id = #{vo.customerId}


    AND c.customer_name LIKE CONCAT('%', #{vo.customerName}, '%')


    AND p.salesman_id = #{vo.salesmanId}


    AND p.stage_name LIKE CONCAT('%', #{vo.stageName}, '%')


    AND p.plan_status = #{vo.planStatus}



    AND p.plan_date >= #{vo.planDate_begin}


    AND p.plan_date <= #{vo.planDate_end}

ORDER BY p.create_time DESC
